+import type {OutgoingHttpHeaders} from 'node:http';
+import lowercaseKeys from 'lowercase-keys';
+import getBodySize from './core/utils/get-body-size.js';
+
+export type UploadBudget = {
+	/**
+	The upload size in bytes, or `undefined` when it cannot be known without consuming the body.
+	*/
+	bytes: number | undefined;
+
+	/**
+	Whether the upload fits within the limit, or `null` when the size cannot be known without consuming the body.
+	*/
+	fits: boolean | null; // eslint-disable-line @typescript-eslint/ban-types
+};
+
+/**
+Determine whether an upload fits a byte budget before opening a connection.
+
+An explicit `content-length` header takes priority. Strings are measured in UTF-8 bytes and a missing body counts as zero bytes. Streams are never consumed.
+
+@param body - The request body.
+@param headers - The request headers.
+@param limit - The maximum number of bytes allowed.
+*/
+export async function uploadFits(body: unknown, headers: OutgoingHttpHeaders | undefined, limit: number): Promise<UploadBudget> {
+	if (!Number.isFinite(limit) || limit < 0) {
+		throw new RangeError(`Expected \`limit\` to be a non-negative finite number, got ${limit}`);
+	}
+
+	const size = await getBodySize(body, headers && lowercaseKeys(headers));
+
+	if (size === undefined || !Number.isFinite(size) || size < 0) {
+		return {bytes: undefined, fits: null};
+	}
+
+	return {bytes: size, fits: size <= limit};
+}
diff --git a/test/upload-budget.ts b/test/upload-budget.ts
new file mode 100644
index 0000000..7599179
--- /dev/null
+++ b/test/upload-budget.ts
@@ -0,0 +1,61 @@
+import {Buffer} from 'node:buffer';
+import {Readable} from 'node:stream';
+import test from 'ava';
+import FormData from 'form-data';
+import {uploadFits} from '../source/upload-budget.js';
+
+test('no body is zero bytes', async t => {
+	t.deepEqual(await uploadFits(undefined, {}, 0), {bytes: 0, fits: true});
+	t.deepEqual(await uploadFits(undefined, undefined, 10), {bytes: 0, fits: true});
+});
+
+test('strings are measured in UTF-8 bytes', async t => {
+	t.deepEqual(await uploadFits('€', {}, 3), {bytes: 3, fits: true});
+	t.deepEqual(await uploadFits('€', {}, 2), {bytes: 3, fits: false});
+});
+
+test('buffers use their byte length', async t => {
+	t.deepEqual(await uploadFits(Buffer.alloc(5), {}, 4), {bytes: 5, fits: false});
+});
+
+test('explicit content-length takes priority', async t => {
+	t.deepEqual(await uploadFits('hello', {'content-length': '2'}, 3), {bytes: 2, fits: true});
+	t.deepEqual(await uploadFits('hello', {'Content-Length': 100}, 50), {bytes: 100, fits: false});
+});
+
+test('content-length applies to streams', async t => {
+	const stream = Readable.from(['abc']);
+	t.deepEqual(await uploadFits(stream, {'content-length': '3'}, 3), {bytes: 3, fits: true});
+});
+
+test('unknown size streams are not consumed', async t => {
+	const stream = Readable.from(['abc']);
+	t.deepEqual(await uploadFits(stream, {}, 10), {bytes: undefined, fits: null});
+	t.false(stream.readableEnded);
+	t.is(stream.readableLength, 0);
+
+	const chunks: string[] = [];
+	for await (const chunk of stream) {
+		chunks.push(chunk as string);
+	}
+
+	t.deepEqual(chunks, ['abc']);
+});
+
+test('invalid content-length is unknown', async t => {
+	t.deepEqual(await uploadFits('hello', {'content-length': 'nope'}, 10), {bytes: undefined, fits: null});
+});
+
+test('form-data length is computed without consuming', async t => {
+	const form = new FormData();
+	form.append('a', 'b');
+	const expected = form.getLengthSync();
+	t.deepEqual(await uploadFits(form, {}, expected), {bytes: expected, fits: true});
+});
+
+test('rejects invalid limits', async t => {
+	for (const limit of [-1, Number.NaN, Number.POSITIVE_INFINITY]) {
+		// eslint-disable-next-line no-await-in-loop
+		await t.throwsAsync(uploadFits('', {}, limit), {instanceOf: RangeError});
+	}
+});
